#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=12

# ── Showcase helpers ──────────────────────────────────────────────────────
# The wizard drives Codino itself; the human watches the Device. It works the
# same with the Virtual Device (a daemon started with --virtual-device).

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO"
CODINO="$REPO/codino"
WORK=$(mktemp -d)
CONFIG="${CODINO_CONFIG:-${XDG_CONFIG_HOME:-$HOME/.config}/codino/config.toml}"
HAD_CONFIG=0
SESSIONS=()  # every session id this run created
THEMES=()    # installed here, uninstalled on the way out ("--sprite-pack NAME" for a pack)
SHOW_PID=""
GO=""

# codino ARGS — run the codino under test, echoing the command first.
codino() {
  printf '  %s$ codino %s%s\n' "$DIM" "$*" "$RESET"
  "$CODINO" "$@"
}

# ev ID ARGS — an event for a showcase session (ids are prefixed, and ended on exit).
ev() {
  local id="showcase-$1"; shift
  [[ " ${SESSIONS[*]} " == *" $id "* ]] || SESSIONS+=("$id")
  codino event --session "$id" "$@"
}

# end ID... — end showcase sessions.
end() {
  local id
  for id in "$@"; do codino event --session "showcase-$id" --end; done
}

# look "what to look for" ["prompt"] — tell the human what the matrix shows, then wait.
SEEN="Press Enter when you've seen it"
look() {
  printf '  %s👀 %s%s\n' "$GREEN" "$1" "$RESET"
  pause "${2:-$SEEN}"
}

# countdown SECONDS "label" — wait in place, so timed behaviour can be watched.
countdown() {
  local i
  for ((i = $1; i > 0; i--)); do
    printf '\r  %s⏱ %s: %3ds%s ' "$DIM" "$2" "$i" "$RESET"
    sleep 1
  done
  printf '\r  %s⏱ %s: done %s\n' "$DIM" "$2" "$RESET"
}

claimed() { "$CODINO" status 2>/dev/null | grep -q '(firmware'; }
running() { ! "$CODINO" status 2>/dev/null | grep -q 'not running'; }

# cleanup — on any exit: stop Raw Mode, end the sessions, uninstall what was
# installed, and put the human's config file back as it was.
cleanup() {
  set +e
  [[ -n "$SHOW_PID" ]] && kill -TERM "$SHOW_PID" 2>/dev/null
  if running; then
    local id t
    for id in "${SESSIONS[@]}"; do "$CODINO" event --session "$id" --end >/dev/null 2>&1; done
    for t in "${THEMES[@]}"; do
      # shellcheck disable=SC2086 # "--sprite-pack NAME" splits on purpose
      timeout 15 "$CODINO" theme uninstall $t >/dev/null 2>&1
    done
  fi
  if ((HAD_CONFIG)); then
    cat "$WORK/config.toml" >"$CONFIG" # through a symlink, as codino set does
  else
    rm -f "$CONFIG"
  fi
  rm -rf "$WORK"
  printf '  %sYour Preferences are restored (%s).%s\n' "$DIM" "$CONFIG" "$RESET"
}
trap cleanup EXIT

# png FILE — write a 64×64 picture: red grows to the right, green downwards,
# a blue disc in the middle. Python's stdlib only.
png() {
  python3 - "$1" <<'EOF'
import struct, sys, zlib
w = h = 64
rows = b""
for y in range(h):
    rows += b"\0"
    for x in range(w):
        d = (x - 31.5) ** 2 + (y - 31.5) ** 2
        rows += bytes((x * 4, y * 4, 255 if d < 15 ** 2 else 0))
def chunk(kind, data):
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data))
open(sys.argv[1], "wb").write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
                              + chunk(b"IDAT", zlib.compress(rows)) + chunk(b"IEND", b""))
EOF
}

banner "Codino showcase"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: the binary, the Host Daemon, the Device"
say "Builds codino, checks that a Host Daemon has claimed your Device, and"
say "starts every Preference from its default (your config comes back at the end)."
for g in go /usr/local/go/bin/go; do
  if command -v "$g" >/dev/null 2>&1 && "$g" build -o "$CODINO" ./cmd/codino 2>/dev/null; then GO="$g"; break; fi
done
[[ -n "$GO" ]] || { warn "go build failed: the repo needs the Go in go.mod (try /usr/local/go/bin first on PATH)"; exit 1; }
note "built ./codino with $("$GO" version | cut -d' ' -f3)"
while ! claimed; do
  warn "no Device is claimed yet."
  step "Plug the Device in, then in another terminal run:  cd $REPO && ./codino daemon"
  note "(no board? ./codino daemon --virtual-device device/build/virtual-device)"
  pause "Press Enter to check again"
done
codino status
if [[ -f "$CONFIG" ]]; then cp "$CONFIG" "$WORK/config.toml"; HAD_CONFIG=1; fi
for k in theme brightness layout rotation quiet_mode done_decay escalation.faster escalation.takeover escalation.steady; do
  "$CODINO" unset "$k" >/dev/null 2>&1 || true
done
note "Preferences at their defaults; yours are saved in $WORK."
if "$CODINO" status | grep -q '^[0-9]'; then
  warn "other sessions are open (above): they share the matrix with the showcase."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Session States"
say "One Agent Session on the whole matrix, through each Session State."
ev a --state idle --project "$REPO"
look "Idle: Nino, the mascot, resting in a dim lavender."
ev a --state working
look "Working: Nino busy in blue, scrolling."
ev a --state done
look "Done: Nino in green."
ev a --state error
look "Error: Nino in red, blinking once a second."
end a
look "Session ended: the matrix goes dark."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Awaiting Input and Escalation"
say "Escalation is shortened for the demo: faster at 10 s, Takeover at 20 s,"
say "steady at 40 s (the defaults are 30 s, 2 min and 10 min)."
codino set escalation.faster 10s
codino set escalation.takeover 20s
codino set escalation.steady 40s
pause "Press Enter to put a session Awaiting Input"
ev a --state awaiting_input --project "$REPO"
note "0 s gentle amber pulse · 10 s faster and brighter · 20 s Takeover in the Project Color · 40 s steady glow"
countdown 45 "Escalation"
look "It settled into a steady glow."
ev a --acknowledge
look "Acknowledged (as a typed prompt would): back to the gentle pulse; Escalation starts over."
end a
for k in escalation.faster escalation.takeover escalation.steady; do codino unset "$k"; done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Adaptive Layout and Project Colors"
say "Several sessions get Tiles, each in its project's color. A folder outside"
say "git is a project of its own, so these make three projects."
P2="$WORK/p2"; P3="$WORK/p3"; mkdir -p "$P2" "$P3"
ev l1 --state working --project "$REPO"
ev l2 --state done --project "$P2"
look "Two sessions: two halves, in two Project Colors."
ev l3 --state idle --project "$P3"
ev l4 --state error --project "$REPO"
look "Four: quadrants. The two sessions of this repo share its color."
for i in 5 6 7 8; do ev "l$i" --state working --project "$P2"; done
look "Eight: one column each."
ev l9 --state idle --project "$P3"
look "Nine: seven columns, and the last one is the Overflow Tile for the rest."
codino set "project_colors.$REPO" "#ffffff"
look "Pinned this repo to white: its sessions recolor at once."
codino unset "project_colors.$REPO"
end l1 l2 l3 l4 l5 l6 l7 l8 l9

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Aggregate Layout"
say "The Aggregate Layout shows only the most urgent state of all the sessions:"
say "Awaiting Input > Error > Done > Working > Idle."
codino set layout aggregate
ev g1 --state idle --project "$REPO"
look "Idle alone."
ev g2 --state working --project "$P2"
look "Working beats Idle."
ev g3 --state done --project "$P3"
look "Done beats Working."
ev g4 --state error --project "$REPO"
look "Error beats Done."
ev g5 --state awaiting_input --project "$P2"
look "Awaiting Input beats everything."
end g5
look "It ends: Error wins again."
end g1 g2 g3 g4
codino unset layout

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Done decay and Acknowledge"
say "Done fades back to Idle after the Done decay (10 min by default; 15 s here)."
codino set done_decay 15s
ev d --state done --project "$REPO"
countdown 17 "Done decay"
look "Back to Idle on its own."
ev d --state done
look "Done again."
ev d --acknowledge
look "Acknowledged: Idle at once."
end d
codino unset done_decay

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Brightness, rotation and Quiet Mode"
ev q1 --state working --project "$REPO"
codino set brightness 10
look "Brightness 10%: dim, but still lit."
codino set brightness 100
look "Brightness 100%: the Device's brightness cap."
for r in 90 180 270; do
  codino set rotation "$r"
  look "Rotation $r°: Nino turns clockwise."
done
codino unset rotation
codino set quiet_mode true
look "Quiet Mode: Working goes dark."
ev q2 --state awaiting_input --project "$P2"
look "...but Awaiting Input always shows."
end q2
codino unset quiet_mode
end q1
codino unset brightness

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Themes"
say "Every state's look is data. Built in: default (Nino) and minimal."
ev t --state working --project "$REPO"
codino set theme minimal
look "minimal: an abstract fill instead of Nino."
codino theme install themes/examples/neon.json && THEMES+=("neon")
codino set theme neon
look "neon, installed from themes/examples/: its own colors and effects."
codino theme install themes/examples/my-pack.json && THEMES+=("--sprite-pack my-pack")
codino theme install themes/examples/my-character.json && THEMES=("my-character" "${THEMES[@]}")
codino set theme my-character
look "my-character: a Character Theme drawing its own Sprite Pack."
codino theme list
pause
codino set theme default
codino theme uninstall my-character
codino theme uninstall --sprite-pack my-pack
codino theme uninstall neon
THEMES=()
end t
look "Back to the default Theme; the examples are uninstalled."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Raw Mode"
say "codino show puts any PNG, JPEG or GIF on the matrix, scaled to fit."
if command -v python3 >/dev/null 2>&1; then
  png "$WORK/showcase.png"
  printf '  %s$ codino show showcase.png &%s\n' "$DIM" "$RESET"
  "$CODINO" show "$WORK/showcase.png" &
  SHOW_PID=$!
  look "A gradient (red to the right, green downwards) with a blue disc in the middle."
  ev r --state awaiting_input --project "$REPO"
  look "Awaiting Input pre-empts the picture..."
  end r
  look "...and the picture comes back."
  kill -TERM "$SHOW_PID"; wait "$SHOW_PID" 2>/dev/null || true; SHOW_PID=""
  look "codino show stopped: Raw Mode ends."
else
  warn "python3 isn't installed: run  ./codino show SOME.gif  yourself, Ctrl-C to stop."
  SKIPPED+=("Raw Mode (needs python3 for the picture)")
  pause
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Web UI"
say "The web UI edits the Preferences and previews the Device in the browser."
codino ui
step "Drag the brightness: the Device follows within a second."
step "Browse the Themes, and switch between them."
step "Preview each Session State: the browser's Device and the real one show it."
note "Changes made here are undone with the rest of your config at the end."
pause "Press Enter when you're done with the page"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "A real Claude Code session"
say "The plugin's hooks drive the Device from Claude Code."
if PATH="$(dirname "$(command -v "$GO")"):$PATH" make plugin >/dev/null; then
  note "plugin binary built in plugin/bin/"
else
  warn "make plugin failed"; SKIPPED+=("make plugin"); fi
step "In another terminal (keep the Device in view):"
note "    cd $P2 && claude --plugin-dir $REPO/plugin"
look "Claude starts: a new session, Idle." "Press Enter once Claude is up"
step "Prompt: say hi in five words"
look "Working while it answers, then Done."
step "Prompt: run ls / with the Bash tool  (don't approve yet)"
look "The permission prompt: Awaiting Input, escalating like stage 3."
step "Approve it."
look "Working, then Done."
step "Type /exit."
look "The session is removed."
step "Now:  claude --plugin-dir $REPO/plugin --model does-not-exist  and send: hi"
look "The model isn't found: Error, Nino in red, blinking."
step "Type /exit."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Unplugging, Disconnected and goodbye"
ev z --state awaiting_input --project "$REPO"
step "Unplug the Device, wait a few seconds, then plug it into any USB port."
look "It is claimed again and shows the session, Escalation counted from the start." "Press Enter once it's back"
codino status
say "A Host Daemon that dies without a word leaves the Device Disconnected."
if confirm "Kill the Host Daemon with kill -9?"; then
  pkill -9 -f 'codino daemon' || true
  countdown 7 "Disconnected timeout"
  look "Disconnected: a dim diagonal across a dark matrix."
  ev z --state working
  look "codino event spawned a new daemon in the background: it claims the Device, Working."
fi
end z
say "A clean exit says goodbye: the Device goes dark instead."
if confirm "Stop the Host Daemon with SIGTERM?"; then
  pkill -TERM -f 'codino daemon' || true
  look "Dark, not Disconnected."
fi

finish
note "That was every feature. Your Preferences go back as they were."
